public class Calc {
    public double calc(List<Item> items, User u) {
        double t = 0;
        for (Item i : items) {
            double p = i.getP();
            if (u.getT() == 1 && i.getC().equals("FOOD")) p *= 0.9;
            t += p * i.getQ();
        }
        return t > 100 ? t * 0.98 : t;
    }
}
